//! 🧪️ Public reconstruction keeps original blob prefixes and both SQL/native custody.
use super::*;
use semio_framework_value::RetainedCloneGrant;
use semio_framework_value::NativeEncodeControl;
use semio_framework_value_testing_admission::{NativeAllocationEvent,NativeAllocationAuthority,OriginalConstructionAuthority,OriginalWorkAuthority};
#[path="../🧪️support.rs"]
mod support;
use support::{Port,Work,Recipient,close};
#[test]
fn reconstructed_blob_keeps_prefix_and_original_sql_outcome(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();let count=fixture["payloadBytes"].as_u64().unwrap()as usize;let pattern=fixture["pattern"].as_array().unwrap();let source:Vec<u8>=(0..count).map(|i|pattern[i%pattern.len()].as_u64().unwrap()as u8).collect();let g=&fixture["grant"];let grant=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};
 for case in fixture["cases"].as_array().unwrap(){
  let name=case["name"].as_str().unwrap();let refuse=name=="receipt-refused";let physical=Recipient{grant,submitted:Default::default(),refuse:move|progress:semio_framework_value::RetainedCloneProgress|if refuse&&progress.retained_capacity_bytes==0&&progress.copied_bytes!=0{Err(ValueError::literal(ValueRefusalKind::Canceled,"original blob receipt refused"))}else{Ok(())}};let work=Work(8);let mut native_progress=|_|true;let admitted=std::sync::atomic::AtomicUsize::new(0);let mut quoted=None;
  let allocation=|event:NativeAllocationEvent|{match event{NativeAllocationEvent::Admit(request)=>{assert_eq!(request.owned_bytes.checked_add(request.bytes),Some(request.next_owned_bytes));assert!(request.next_owned_bytes<=request.maximum_bytes);},NativeAllocationEvent::Quote(request)=>{assert!(quoted.replace(request).is_none());},NativeAllocationEvent::Post{request,actual}=>{assert_eq!(quoted.take(),Some(request));admitted.fetch_add(actual,std::sync::atomic::Ordering::Relaxed);},NativeAllocationEvent::Cancel(request)=>assert_eq!(quoted.take(),Some(request))};Ok(())};
  let mut callback=|event:semio_framework_io_sqlite_model::SqliteSnapshotProgress|{if name=="sql-progress-panics"&&event.completed==65536&&event.total==count{panic!("original SQL observer panicked")}true};let limits=semio_framework_io_sqlite_model::SqliteDatabaseLimits{max_allocation_bytes:if name=="sql-denied"{count-1}else{count},..Default::default()};let mut control=SqliteSnapshotControl::new(&mut callback,limits);let mut output=Vec::new();let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation_state=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
  let mut allocation_authority=NativeAllocationAuthority::new(Port(allocation));let mut construction=OriginalConstructionAuthority::new(physical);let mut work_authority=OriginalWorkAuthority::new(work);let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||allocation_authority.with_send_loan(&mut (),|allocation_loan|{let mut native=NativeEncodeControl::new_forwarded(grant.maximum_capacity_bytes,&mut native_progress,allocation_loan);construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=SnapshotOwner::Encode(&mut original);let mut reconstruction=super::super::Reconstruction::new(&mut control)?;Ok::<_,ValueError>(reconstruction.blob_into(&mut output,&source,&mut owner,&mut marker,&mut unwind,&mut stage_unwind,&mut allocation_state,1))})))).unwrap().unwrap().unwrap()}).unwrap()));
  allocation_authority.into_port().ok().expect("original allocation authority settled");
  assert_eq!(result.is_err(),name=="sql-progress-panics");let stage=match result{Ok(stage)=>stage,Err(_)=>stage_unwind.take().expect("original SQL unwind outcome")};assert_eq!(stage.work,Some(u128::from(case["work"].as_u64().unwrap())),"{name}");assert_eq!(output.len(),case["prefix"].as_u64().unwrap()as usize);assert_eq!(output,&source[..output.len()]);assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::from_slice::<serde_json::Value>(&serde_json::to_vec(&source[..output.len()]).unwrap()).unwrap());let expected=if output.capacity()==0{0}else{count};assert_eq!(output.capacity(),expected);assert_eq!(admitted.load(std::sync::atomic::Ordering::Relaxed),expected);assert_eq!(control.allocation_bytes(),expected);close(output,grant);close(stage,grant);close(allocation_state,grant);if let Some(failure)=unwind{close(failure,grant);}
 }
}
